<?phpnamespace app\api\controller\exchange;use app\api\controller\Controller;use app\api\model\exchange\Order as OrderModel;/** * 兑换订单控制器 */class Order extends Controller{    /**     * 我的所有类型订单列表     */    public function all()    {        $model = new OrderModel;        $list = [            0 => $model->getList('receipt','',$this->user_id),            1 => $model->getList('complete','',$this->user_id),        ];        return $this->renderSuccess($list);    }    /**     * 获取兑换记录     */    public function lists(string $dataType)    {        $model = new OrderModel;        $list = $model->getList($dataType,'',$this->user_id);        return $this->renderSuccess($list);    }    /**     * 添加订单     */    public function add()    {        $model = new OrderModel;        if ($model->add($this->request->post())) {            return $this->renderMsg('兑换成功');        }        $error = $model->getError() ?: '兑换失败';		return $this->renderError($error);    }}